// One API call per unique person. Duplicate CSV rows are dropped here, not paid for.
const seen = {};
const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const j = items[i].json;
  const first = String(j.firstName || '').trim();
  const middle = String(j.middleName || '').trim();
  const last = String(j.lastName || '').trim();
  const city = String(j.city || '').trim();
  const state = String(j.state || '').trim().toUpperCase();

  const key = [first, middle, last, city, state].join('|').toUpperCase();
  if (seen[key]) continue;
  seen[key] = true;

  let candidates = parseInt(String(j.candidates || '1'), 10);
  if (isNaN(candidates) || candidates < 1) candidates = 1;
  const cap = Number($('Workflow Settings').first().json.max_candidates_cap) || 3;
  if (candidates > cap) candidates = cap;

  out.push({
    json: {
      subject_id: String(out.length + 1),
      firstName: first,
      middleName: middle,
      lastName: last,
      city: city,
      state: state,
      candidates: candidates,
      searched_name: [first, middle, last].filter(Boolean).join(' '),
      searched_city: city,
      searched_state: state,
    },
    pairedItem: { item: i },
  });
}

return out;

// One row per report token. LIMIT on the People Search call caps how many
// candidates come back; this also hard-caps it so a wide name never fans out.
function toArray(value) {
  if (value === null || value === undefined) return [];
  return Array.isArray(value) ? value : [value];
}

const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const j = items[i].json;
  const max = Number(j.max_candidates) > 0 ? Number(j.max_candidates) : 1;
  const people = toArray(j.people).slice(0, max);

  for (let p = 0; p < people.length; p++) {
    const token = String((people[p] && people[p].reportToken) || '');
    if (!token) continue;
    out.push({
      json: {
        subject_id: String(j.subject_id || ''),
        searched_name: String(j.searched_name || ''),
        searched_city: String(j.searched_city || ''),
        searched_state: String(j.searched_state || ''),
        candidate_rank: p + 1,
        reportToken: token,
      },
      pairedItem: { item: i },
    });
  }
}

return out;

// Masking is switched on and off in the Workflow Settings node, not here.
const MASK_SSN = $('Workflow Settings').first().json.mask_ssn !== false;

function safe(value) {
  if (value === null || value === undefined) return '';
  if (typeof value === 'object') return '';
  return String(value).trim();
}

function toArray(value) {
  if (value === null || value === undefined) return [];
  return Array.isArray(value) ? value : [value];
}

function nameToFull(n) {
  if (!n || typeof n !== 'object') return safe(n);
  return [
    safe(n.firstName || n.first || ''),
    safe(n.middleName || n.middle || ''),
    safe(n.lastName || n.last || ''),
  ].filter(Boolean).join(' ').trim();
}

function money(value) {
  if (value === null || value === undefined || value === '') return null;
  const n = parseFloat(String(value).replace(/[^0-9.-]/g, ''));
  return isNaN(n) ? null : n;
}

function maskSsn(ssn) {
  const digits = safe(ssn).replace(/[^0-9]/g, '');
  if (!digits) return '';
  if (!MASK_SSN) return safe(ssn);
  return digits.length >= 4 ? 'XXX-XX-' + digits.slice(-4) : 'XXX-XX-XXXX';
}

// The report API is 1:1 with its input, so context lines up by index.
const context = $('Extract Candidates').all();
const searchDate = new Date().toISOString().slice(0, 10);
const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const ctx = (context[i] && context[i].json) || {};
  const raw = items[i].json;
  const person = Array.isArray(raw) ? raw[0] : (raw && raw.person ? raw.person : raw);

  const row = {
    SUBJECT_ID: safe(ctx.subject_id),
    SEARCHED_NAME: safe(ctx.searched_name),
    SEARCHED_CITY: safe(ctx.searched_city),
    SEARCHED_STATE: safe(ctx.searched_state),
    CANDIDATE_RANK: Number(ctx.candidate_rank) || 1,
    REPORT_TOKEN: safe(ctx.reportToken),
    FULL_NAME: '', DOB: '', SSN_MASKED: '',
    ADDRESS: '', CITY: '', STATE: '', ZIP: '', ADDRESS_COUNT: 0,
    PHONES: '', PHONE_COUNT: 0, EMAILS: '', EMAIL_COUNT: 0,
    RELATIVE_COUNT: 0, RELATIVE_NAMES: '',
    BUSINESS_COUNT: 0, BUSINESS_NAME: '',
    SHARED_SSN_COUNT: 0, SHARED_SSN_NAME: '',
    LIEN_COUNT: 0, TOTAL_LIEN_AMOUNT: 0,
    HAS_SSN: 'No',
    SEARCH_DATE: searchDate,
    _addresses: [],
  };

  if (!person || typeof person !== 'object' || raw.error) {
    row.FULL_NAME = 'REPORT_UNAVAILABLE';
    out.push({ json: row, pairedItem: { item: i } });
    continue;
  }

  row.REPORT_TOKEN = safe(person.reportToken) || row.REPORT_TOKEN;

  const names = toArray(person.names && person.names.name);
  row.FULL_NAME = nameToFull(names[0]);

  const dob = (person.DOBs && person.DOBs.DOB) || {};
  row.DOB = [dob.month, dob.day, dob.year].filter(Boolean).join('/');

  const ssn = safe(person.SSNs && person.SSNs.SSNRecord && person.SSNs.SSNRecord.SSN);
  row.SSN_MASKED = maskSsn(ssn);
  row.HAS_SSN = ssn ? 'Yes' : 'No';

  const addresses = toArray(person.addresses && person.addresses.address);
  row.ADDRESS_COUNT = addresses.length;
  const first = addresses[0] || {};
  row.ADDRESS = safe(first.line1);
  row.CITY = safe(first.city);
  row.STATE = safe(first.state);
  row.ZIP = safe(first.zip);
  row._addresses = addresses.map((a, idx) => ({
    rank: idx + 1,
    line1: safe(a && a.line1),
    city: safe(a && a.city),
    state: safe(a && a.state),
    zip: safe(a && a.zip),
    county: safe(a && (a.county || a.countyName)),
    first_seen: safe(a && (a.dateFirstSeen || a.firstReported || a.dateFirstReported)),
    last_seen: safe(a && (a.dateLastSeen || a.lastReported || a.dateLastReported)),
  }));

  const phones = toArray(person.phones && person.phones.phone);
  row.PHONE_COUNT = phones.length;
  row.PHONES = phones
    .map((p) => {
      const number = safe(p && p.phoneNumber);
      if (!number) return '';
      const meta = [safe(p.phoneType), safe(p.carrier)].filter(Boolean).join(', ');
      return meta ? number + ' (' + meta + ')' : number;
    })
    .filter(Boolean).join(' | ');

  const emails = toArray(person.emails && person.emails.email).map(safe).filter(Boolean);
  row.EMAIL_COUNT = emails.length;
  row.EMAILS = emails.join(' | ');

  const relatives = toArray(person.relatives && person.relatives.relative);
  row.RELATIVE_COUNT = relatives.length;
  row.RELATIVE_NAMES = relatives
    .map((r) => nameToFull(toArray(r && r.names && r.names.name)[0]))
    .filter(Boolean).join(' | ');

  const businesses = toArray(person.businessAssociations && person.businessAssociations.business);
  row.BUSINESS_COUNT = businesses.length;
  row.BUSINESS_NAME = businesses
    .map((b) => safe(b && (b.businessName || b.name || b.companyName)))
    .filter(Boolean).join(' | ');

  const shared = toArray(person.IndividualsSharingSSN && person.IndividualsSharingSSN.IndividualSharingSSN);
  row.SHARED_SSN_COUNT = shared.length;
  row.SHARED_SSN_NAME = shared
    .map((s) => {
      if (!s) return '';
      return nameToFull(toArray(s.names && s.names.name)[0]) || nameToFull(s) || safe(s.fullName);
    })
    .filter(Boolean).join(' | ');

  const liens = toArray(person.personalLienFilings && person.personalLienFilings.personalLienFiling);
  row.LIEN_COUNT = liens.length;
  const amounts = liens
    .map((l) => money(l && (l.amount != null ? l.amount : (l.lienAmount != null ? l.lienAmount : (l.filingAmount != null ? l.filingAmount : l.totalAmount)))))
    .filter((n) => n !== null);
  row.TOTAL_LIEN_AMOUNT = amounts.reduce((sum, n) => sum + n, 0);

  out.push({ json: row, pairedItem: { item: i } });
}

return out;

// MATCH_SCORE: how well the returned report matches what was actually searched.
// 45 last name + 35 first name + 20 state, half credit for a prefix match.
function norm(value) {
  return String(value === null || value === undefined ? '' : value)
    .toUpperCase().replace(/[^A-Z ]/g, ' ').replace(/\s+/g, ' ').trim();
}

function part(searched, found) {
  if (!searched || !found) return 0;
  if (searched === found) return 1;
  if (found.startsWith(searched) || searched.startsWith(found)) return 0.5;
  return 0;
}

// Every threshold below comes from the Workflow Settings node - change them
// there and the scoring follows, no JavaScript editing required.
const cfg = $('Workflow Settings').first().json;
const LIEN_LIMIT = Number(cfg.risk_lien_threshold) || 10000;
const ADDRESS_LIMIT = Number(cfg.many_addresses_at) || 5;
const WEAK_MATCH_BELOW = Number(cfg.weak_match_below) || 70;

const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const row = Object.assign({}, items[i].json);

  const searched = norm(row.SEARCHED_NAME).split(' ').filter(Boolean);
  const found = norm(row.FULL_NAME).split(' ').filter(Boolean);
  const searchedFirst = searched[0] || '';
  const searchedLast = searched.length > 1 ? searched[searched.length - 1] : '';
  const foundFirst = found[0] || '';
  const foundLast = found.length > 1 ? found[found.length - 1] : '';

  let score = 0;
  score += 35 * part(searchedFirst, foundFirst);
  score += 45 * part(searchedLast, foundLast);
  if (norm(row.SEARCHED_STATE) && norm(row.SEARCHED_STATE) === norm(row.STATE)) score += 20;
  if (row.FULL_NAME === 'REPORT_UNAVAILABLE') score = 0;
  row.MATCH_SCORE = Math.round(score);

  // A call that never returned a report says nothing about the person, so it
  // carries one flag and no risk level rather than a pile of false negatives.
  const flags = [];
  if (row.FULL_NAME === 'REPORT_UNAVAILABLE') {
    flags.push('REPORT_UNAVAILABLE');
    row.FLAGS = flags.join(', ');
    row.RISK_LEVEL = 'UNKNOWN';
    out.push({ json: row, pairedItem: { item: i } });
    continue;
  }

  if (Number(row.SHARED_SSN_COUNT) > 0) flags.push('SHARED_SSN');
  if (Number(row.LIEN_COUNT) > 0) flags.push('LIENS');
  if (Number(row.ADDRESS_COUNT) >= ADDRESS_LIMIT) flags.push('MANY_ADDRESSES');
  if (row.HAS_SSN !== 'Yes') flags.push('NO_SSN_ON_FILE');
  if (row.MATCH_SCORE < WEAK_MATCH_BELOW) flags.push('WEAK_NAME_MATCH');
  row.FLAGS = flags.join(', ');

  const bigLien = Number(row.TOTAL_LIEN_AMOUNT) >= LIEN_LIMIT;
  if (flags.indexOf('SHARED_SSN') !== -1 || bigLien) row.RISK_LEVEL = 'HIGH';
  else if (flags.indexOf('LIENS') !== -1 || flags.indexOf('MANY_ADDRESSES') !== -1) row.RISK_LEVEL = 'MEDIUM';
  else row.RISK_LEVEL = 'LOW';

  out.push({ json: row, pairedItem: { item: i } });
}

return out;

// One row per address on file, newest first as returned by the report.
const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const row = items[i].json;
  const addresses = Array.isArray(row._addresses) ? row._addresses : [];

  for (let a = 0; a < addresses.length; a++) {
    const addr = addresses[a];
    out.push({
      json: {
        SUBJECT_ID: row.SUBJECT_ID,
        REPORT_TOKEN: row.REPORT_TOKEN,
        FULL_NAME: row.FULL_NAME,
        ADDRESS_RANK: addr.rank,
        IS_CURRENT: addr.rank === 1 ? 'Yes' : 'No',
        LINE1: addr.line1,
        CITY: addr.city,
        STATE: addr.state,
        ZIP: addr.zip,
        COUNTY: addr.county,
        FIRST_SEEN: addr.first_seen,
        LAST_SEEN: addr.last_seen,
        SEARCH_DATE: row.SEARCH_DATE,
      },
      pairedItem: { item: i },
    });
  }
}

return out;

// One row per person searched, whatever the number of candidate reports.
const rank = { UNKNOWN: -1, LOW: 0, MEDIUM: 1, HIGH: 2 };
const groups = {};
const order = [];

for (const item of $input.all()) {
  const j = item.json;
  const key = String(j.SUBJECT_ID || '');

  if (!groups[key]) {
    order.push(key);
    groups[key] = {
      SUBJECT_ID: key,
      SEARCHED_NAME: j.SEARCHED_NAME || '',
      SEARCHED_CITY: j.SEARCHED_CITY || '',
      SEARCHED_STATE: j.SEARCHED_STATE || '',
      CANDIDATES_FOUND: 0,
      BEST_MATCH_NAME: '',
      BEST_MATCH_SCORE: -1,
      RISK_LEVEL: 'LOW',
      FLAGS: {},
      ADDRESS_COUNT: 0,
      RELATIVE_COUNT: 0,
      LIEN_COUNT: 0,
      TOTAL_LIEN_AMOUNT: 0,
      HAS_SHARED_SSN: 'No',
    };
  }

  const g = groups[key];
  g.CANDIDATES_FOUND++;

  const score = Number(j.MATCH_SCORE) || 0;
  if (score > g.BEST_MATCH_SCORE) {
    g.BEST_MATCH_SCORE = score;
    g.BEST_MATCH_NAME = j.FULL_NAME || '';
    g.ADDRESS_COUNT = Number(j.ADDRESS_COUNT) || 0;
    g.RELATIVE_COUNT = Number(j.RELATIVE_COUNT) || 0;
  }

  g.LIEN_COUNT += Number(j.LIEN_COUNT) || 0;
  g.TOTAL_LIEN_AMOUNT += Number(j.TOTAL_LIEN_AMOUNT) || 0;
  if (Number(j.SHARED_SSN_COUNT) > 0) g.HAS_SHARED_SSN = 'Yes';

  String(j.FLAGS || '').split(',').map((f) => f.trim()).filter(Boolean)
    .forEach((f) => { g.FLAGS[f] = true; });

  if ((rank[j.RISK_LEVEL] || 0) > (rank[g.RISK_LEVEL] || 0)) g.RISK_LEVEL = j.RISK_LEVEL;
}

const summaryDate = new Date().toISOString().slice(0, 10);

return order.map((key) => {
  const g = groups[key];
  return {
    json: {
      SUBJECT_ID: g.SUBJECT_ID,
      SEARCHED_NAME: g.SEARCHED_NAME,
      SEARCHED_CITY: g.SEARCHED_CITY,
      SEARCHED_STATE: g.SEARCHED_STATE,
      CANDIDATES_FOUND: g.CANDIDATES_FOUND,
      BEST_MATCH_NAME: g.BEST_MATCH_NAME,
      BEST_MATCH_SCORE: g.BEST_MATCH_SCORE < 0 ? 0 : g.BEST_MATCH_SCORE,
      RISK_LEVEL: g.RISK_LEVEL,
      FLAGS: Object.keys(g.FLAGS).join(', '),
      ADDRESS_COUNT: g.ADDRESS_COUNT,
      RELATIVE_COUNT: g.RELATIVE_COUNT,
      LIEN_COUNT: g.LIEN_COUNT,
      TOTAL_LIEN_AMOUNT: g.TOTAL_LIEN_AMOUNT,
      HAS_SHARED_SSN: g.HAS_SHARED_SSN,
      SUMMARY_DATE: summaryDate,
    },
  };
});
